	["Bigger text, easy to read from a distance."] = "Größerer Text, auch aus der Ferne gut lesbar.",
	["Bigger windows in the EldoUI theme; a new whisper opens its window (after the fight in combat)."] = "Größere Fenster im EldoUI-Thema; ein neues Flüstern öffnet sein Fenster (im Kampf erst danach).",
	["Bin button size"] = "Schaltflächengröße im Sammler",
