	["Blizzard (Edit Mode)"] = "Blizzard (Bearbeitungsmodus)",
	["Blizzard UI decides: Replace gives the EldoUI minimap, Skin gives Blizzard's a flat look, Improve adds the text and extras below."] = "Blizzard-UI entscheidet: Ersetzen gibt die EldoUI-Minikarte, Skin gibt Blizzards Minikarte eine flache Optik, Verbessern fügt den Text und die Extras unten hinzu.",
	["Blizzard alert scale"] = "Skalierung der Blizzard-Warnungen",
	["Blizzard changed the talent tree since the planner read it. Open the planner to check your plan, then try again."] = "Blizzard hat den Talentbaum geändert, seit der Planer ihn gelesen hat. Öffnet den Planer, um Euren Plan zu prüfen, und versucht es dann erneut.",
	["Blizzard clock"] = "Blizzard-Uhr",
	["Blizzard default"] = "Blizzard-Standard",
	["Blizzard extras only"] = "Nur Blizzard-Extras",
	["Blizzard frames"] = "Blizzard-Rahmen",
	["Blizzard plus"] = "Blizzard plus",
	["Blizzard rows"] = "Blizzard-Zeilen",
	["Blizzard switches"] = "Blizzard-Schalter",
	["Blizzard's"] = "Blizzards",
	["Blizzard's \"Enemy units\" nameplate setting."] = "Blizzards Namensplaketten-Einstellung „Feindliche Einheiten“.",
	["Blizzard's \"Enemy units\" plate setting in this kind of place. Game setting uses the row above."] = "Blizzards Plaketteneinstellung „Feindliche Einheiten“ an dieser Art von Ort. Spieleinstellung nutzt die Zeile darüber.",
	["Blizzard's \"Friendly players\" nameplate setting."] = "Blizzards Namensplaketten-Einstellung „Freundliche Spieler“.",
	["Blizzard's \"Friendly players\" plate setting in this kind of place."] = "Blizzards Plaketteneinstellung „Freundliche Spieler“ an dieser Art von Ort.",
	["Blizzard's -/+ buttons fold the tracker and its sections. Quality of Life adds a button and /eui tracker that remember it per character."] = "Blizzards Schaltflächen -/+ klappen die Verfolgung und ihre Abschnitte ein. Komfortfunktionen fügt eine Schaltfläche und /eui tracker hinzu, die das pro Charakter speichern.",
	["Blizzard's UI widgets: battleground scores and capture bars, world objectives and the encounter bar. These follow Blizzard UI > UI widgets."] = "Blizzards UI-Widgets: Schlachtfeldpunkte und Eroberungsleisten, Weltziele und die Begegnungsleiste. Diese folgen Blizzard-UI > UI-Widgets.",
	["Blizzard's achievement window where the game shows it."] = "Blizzards Erfolgsfenster, wo das Spiel es zeigt.",
	["Blizzard's bars"] = "Blizzards Leisten",
	["Blizzard's calendar button with the date and invites."] = "Blizzards Kalenderschaltfläche mit Datum und Einladungen.",
	["Blizzard's cast bars under its target and focus frames. EldoUI's own frames have their own cast bars."] = "Blizzards Zauberleisten unter seinem Ziel- und Fokusrahmen. EldoUIs eigene Rahmen haben eigene Zauberleisten.",
	["Blizzard's clock button (alarm and stopwatch). EldoUI's own clock text is under Text."] = "Blizzards Uhr-Schaltfläche (Wecker und Stoppuhr). Der eigene Uhrtext von EldoUI steht unter Text.",
	["Blizzard's collapse buttons drawn as a small arrow: down while a section is open, right while it is folded. The click stays Blizzard's."] = "Blizzards Einklappschaltflächen als kleiner Pfeil: nach unten, solange ein Abschnitt offen ist, nach rechts, solange er eingeklappt ist. Der Klick bleibt Blizzards.",
	["Blizzard's font and gold headers; only the position comes from EldoUI."] = "Blizzards Schrift und goldene Überschriften; nur die Position kommt von EldoUI.",
	["Blizzard's free bag slot count on the backpack button (a game setting). \"Leave as it is\" never changes it."] = "Blizzards Anzeige freier Taschenplätze auf der Rucksack-Schaltfläche (eine Spieleinstellung). „Unverändert lassen“ ändert sie nie.",
	["Blizzard's happiness icon for hunter pets, with its tooltip."] = "Blizzards Zufriedenheitssymbol für Jägertiere, mit seinem Tooltip.",
	["Blizzard's item interaction window, where the game uses it."] = "Blizzards Fenster für Gegenstandsinteraktion, wo das Spiel es nutzt.",
	["Blizzard's loot alerts (game setting)."] = "Blizzards Beutehinweise (Spieleinstellung).",
	["Blizzard's mailbox. Its size (mouse wheel on the title bar), dragging and resets are on the Move windows page with the other Blizzard windows; where it opens is its mover in move mode (/eui move)."] = "Blizzards Briefkasten. Größe (Mausrad auf der Titelleiste), Ziehen und Zurücksetzen stehen mit den anderen Blizzard-Fenstern auf der Seite Fenster verschieben; wo er sich öffnet, legt sein Verschiebefeld im Verschiebemodus fest (/eui move).",
	["Blizzard's menu of addon buttons."] = "Blizzards Menü der Addon-Schaltflächen.",
	["Blizzard's merchant window. Its size, dragging and resets are on the Move windows page; where it opens is its mover in move mode."] = "Blizzards Händlerfenster. Größe, Ziehen und Zurücksetzen stehen auf der Seite Fenster verschieben; wo es sich öffnet, legt sein Verschiebefeld im Verschiebemodus fest.",
	["Blizzard's nameplate settings. \"Game setting\" leaves yours alone; other values are put back when nameplates return to Blizzard default."] = "Blizzards Namensplaketten-Einstellungen. „Spieleinstellung“ lässt Eure in Ruhe; andere Werte werden zurückgesetzt, wenn die Namensplaketten zu Blizzard-Standard zurückkehren.",
	["Blizzard's nameplates update fully again after a reload."] = "Blizzards Namensplaketten aktualisieren sich nach einem Neuladen wieder vollständig.",
	["Blizzard's own border and font, with the info area added."] = "Blizzards eigener Rand und eigene Schrift, mit hinzugefügtem Infobereich.",
	["Blizzard's own health values in a thin bar under the tooltip."] = "Blizzards eigene Gesundheitswerte in einer dünnen Leiste unter dem Tooltip.",
	["Blizzard's own layout text, selected. Press Ctrl+C, then use Edit Mode > Layouts > Import."] = "Blizzards eigener Layouttext, markiert. Drückt Strg+C und nutzt dann Bearbeitungsmodus > Layouts > Importieren.",
	["Blizzard's own look with EldoUI's extras on top."] = "Blizzards eigene Optik mit EldoUIs Extras obendrauf.",
	["Blizzard's own look, with EldoUI's helpers: menu button, conflict tags, presets and DELETE."] = "Blizzards eigene Optik mit EldoUIs Helfern: Menüschaltfläche, Konfliktmarken, Vorlagen und LÖSCHEN.",
	["Blizzard's own name-only plates for friendly players. Also works inside instances, where friendly plates always stay Blizzard's."] = "Blizzards eigene Plaketten nur mit Namen für freundliche Spieler. Funktioniert auch in Instanzen, wo freundliche Plaketten immer Blizzards bleiben.",
	["Blizzard's own unit frames have their own switches on the Blizzard UI page (Unit frames tab): keep, skin, move or replace each one."] = "Blizzards eigene Einheitenrahmen haben eigene Schalter auf der Seite Blizzard-UI (Reiter Einheitenrahmen): jeden behalten, skinnen, verschieben oder ersetzen.",
	["Blizzard's own version is showing. Turn on \"Let EldoUI change this\" to use the settings below."] = "Blizzards eigene Version wird angezeigt. Schaltet „EldoUI dies ändern lassen“ ein, um die Einstellungen unten zu nutzen.",
	["Blizzard's plate settings per kind of place: enemy plates, friendly plates and stacking. They win over the rows above while you are there. Applied out of combat when you change zones."] = "Blizzards Plaketteneinstellungen je Art von Ort: feindliche Plaketten, freundliche Plaketten und Stapelung. Dort haben sie Vorrang vor den Zeilen darüber. Wird beim Gebietswechsel außerhalb des Kampfes angewendet.",
	["Blizzard's quest and objective tracker: EldoUI look, mover, height, font, fade in combat and Questie support."] = "Blizzards Quest- und Zielverfolgung: EldoUI-Optik, Verschiebefeld, Höhe, Schrift, Ausblenden im Kampf und Questie-Unterstützung.",
	["Blizzard's rotate setting. \"Leave as it is\" never changes it."] = "Blizzards Einstellung zum Drehen. „Unverändert lassen“ ändert sie nie.",
	["Blizzard's shield icon over the spell icon when the cast can't be interrupted."] = "Blizzards Schildsymbol über dem Zaubersymbol, wenn der Zauber nicht unterbrochen werden kann.",
	["Blizzard's talent window"] = "Blizzards Talentfenster",
	["Blizzard's talent window has changes that aren't applied. Apply or undo them there first."] = "Blizzards Talentfenster hat nicht übernommene Änderungen. Übernehmt sie dort zuerst oder macht sie rückgängig.",
	["Blizzard's tracking menu (herbs, ore, vendors)."] = "Blizzards Aufspürmenü (Kräuter, Erz, Händler).",
	["Blizzard's: the game's own fade, half see-through while you move. EldoUI rules: the visibility settings below (by default see-through while you move, solid under the mouse). Off keeps the map solid."] = "Blizzards: das eigene Ausblenden des Spiels, halb durchsichtig, während Ihr Euch bewegt. EldoUI-Regeln: die Sichtbarkeitseinstellungen unten (standardmäßig durchsichtig in Bewegung, deckend unter der Maus). Aus hält die Karte deckend.",
