	["Drops listed"] = "Gelistete Beute",
	["Drops one totem per press, in element order. The sequence starts over 15 seconds after your last press."] = "Stellt pro Tastendruck ein Totem auf, in der Reihenfolge der Elemente. Die Folge beginnt 15 Sekunden nach Eurem letzten Tastendruck von vorn.",
	["Duel requests from people who aren't friends are declined. Off by default."] = "Duellanfragen von Leuten, die keine Freunde sind, werden abgelehnt. Standardmäßig aus.",
	["Dungeon and raid entrances also show on continent maps."] = "Dungeon- und Schlachtzugseingänge erscheinen auch auf Kontinentkarten.",
