	["EldoUI button"] = "EldoUI-Schaltfläche",
	["EldoUI can't read %s talent links yet. If the site offers a talent string or a talent loadout string of the build, paste that instead."] = "EldoUI kann Talentlinks von %s noch nicht lesen. Bietet die Seite einen Talent-String oder einen Loadout-String des Builds an, fügt stattdessen diesen ein.",
	["EldoUI did not change this setting."] = "EldoUI hat diese Einstellung nicht geändert.",
	["EldoUI doesn't recognize this talent link. It reads talent calculator links from %s, talent strings like 0505-3200-5 and talent loadout strings."] = "EldoUI erkennt diesen Talentlink nicht. Es liest Talentrechner-Links von %s, Talent-Strings wie 0505-3200-5 und Loadout-Strings.",
	["EldoUI font"] = "EldoUI-Schriftart",
	["EldoUI frames around Blizzard's parchment pages and dark text."] = "EldoUI-Rahmen um Blizzards Pergamentseiten und dunkler Text.",
	["EldoUI has nothing to undo for this addon."] = "EldoUI hat für dieses Addon nichts rückgängig zu machen.",
	["EldoUI keybind mode"] = "EldoUI-Tastenbelegungsmodus",
