	["Font size of the zone name."] = "Schriftgröße des Gebietsnamens.",
	["Font size of this text."] = "Schriftgröße dieses Texts.",
	["Food buff"] = "Essensbuff",
	["For \"XP, reputation and honor bars\" in Blizzard UI with Skin or Move. Their width and height stay in Edit Mode."] = "Für „EP-, Ruf- und Ehreleisten“ unter Blizzard-UI mit Skin oder Verschieben. Breite und Höhe bleiben im Bearbeitungsmodus.",
	["For 30 minutes"] = "Für 30 Minuten",
	["For Blizzard's bag bar, once it is on in Blizzard UI. Move and scale gives it a mover; Replace docks the bag buttons on EldoUI's bag window."] = "Für Blizzards Taschenleiste, sobald sie unter Blizzard-UI an ist. Verschieben und skalieren gibt ihr ein Verschiebefeld; Ersetzen dockt die Taschenschaltflächen an EldoUIs Taschenfenster an.",
	["For Blizzard's micro menu, once it is on in Blizzard UI. Move and scale gives it a mover; Replace puts a Menu block on the Info Bar."] = "Für Blizzards Mikromenü, sobald es unter Blizzard-UI an ist. Verschieben und skalieren gibt ihm ein Verschiebefeld; Ersetzen setzt einen Block Menü auf die Infoleiste.",
	["For camping a spawn: loud repeating sound, cards stay until closed, three at once (they grow down over the alert lane)."] = "Zum Campen eines Spawns: lauter, wiederholter Ton, Karten bleiben bis zum Schließen, drei gleichzeitig (sie wachsen nach unten über die Warnspalte).",
	["For group buffs (Fortitude, Intellect, Mark of the Wild), count group members without it, when the game lets addons read their auras."] = "Bei Gruppen-Stärkungszaubern (Seelenstärke, Intelligenz, Mal der Wildnis) die Gruppenmitglieder ohne ihn zählen, wenn das Spiel Addons ihre Auren lesen lässt.",
	["For hunters: a Feed Pet button by the pet frame; one click feeds one piece of food. The [pet:happiness] tag shows happiness."] = "Für Jäger: eine Schaltfläche Tier füttern am Tierrahmen; ein Klick verfüttert ein Stück Futter. Das Tag [pet:happiness] zeigt die Zufriedenheit.",
	["For tanks (the role you picked in setup): remind me when this buff is missing, running out or a higher rank is known."] = "Für Tanks (die Rolle, die Ihr in der Einrichtung gewählt habt): mich erinnern, wenn dieser Stärkungszauber fehlt, ausläuft oder ein höherer Rang bekannt ist.",
	["For tanks (the role you picked in setup): remind me when you know this stance or form and are not in it. A click takes it."] = "Für Tanks (die Rolle, die Ihr in der Einrichtung gewählt habt): mich erinnern, wenn Ihr diese Haltung oder Gestalt kennt und nicht in ihr seid. Ein Klick nimmt sie ein.",
	["For tanks (the role you picked in setup): remind me when your off hand holds no shield."] = "Für Tanks (die Rolle, die Ihr in der Einrichtung gewählt habt): mich erinnern, wenn Eure Schildhand keinen Schild hält.",
	["For your %s. Sold by the demon trainer's vendor."] = "Für Euren Dämon (%s). Verkauft vom Händler des Dämonenlehrers.",
	["Forever may use the talking head only in a few places; check it in game."] = "Forever nutzt den sprechenden Kopf vielleicht nur an wenigen Orten; prüft es im Spiel.",
	["Forever's day and night cycle as a small icon on the map."] = "Der Tag-und-Nacht-Wechsel von Forever als kleines Symbol auf der Karte.",
	["Forever's keyring button next to the bags (when the game offers it)."] = "Die Schlüsselbund-Schaltfläche von Forever neben den Taschen (wenn das Spiel sie anbietet).",
	["Forget added buttons"] = "Hinzugefügte Schaltflächen vergessen",
	["Forget all rares you've met"] = "Alle angetroffenen raren Gegner vergessen",
	["Forget dropped food"] = "Abgelegtes Futter vergessen",
	["Forget every recent recipient on this realm?"] = "Alle letzten Empfänger auf diesem Realm vergessen?",
	["Forget seen cutscenes"] = "Gesehene Zwischensequenzen vergessen",
	["Forget the ability log"] = "Fähigkeitenprotokoll vergessen",
	["Forget the group journal"] = "Gruppentagebuch vergessen",
	["Forget this rare"] = "Diesen raren Gegner vergessen",
