	["Gems and enchants"] = "Edelsteine und Verzauberungen",
	["Gems and enchants count, so the score is what each item gives you right now."] = "Edelsteine und Verzauberungen zählen mit, sodass die Wertung zeigt, was jeder Gegenstand Euch gerade jetzt bringt.",
	["Gems in an item add their stats to its score; their sockets no longer count as empty. Off: every socket counts as empty, valued by the socket weights below."] = "Edelsteine in einem Gegenstand fügen ihre Werte seiner Wertung hinzu; ihre Sockel zählen nicht mehr als leer. Aus: Jeder Sockel zählt als leer und wird nach den Sockelgewichten unten bewertet.",
	["Give a group channel a window first."] = "Gebt zuerst einem Gruppenkanal ein Fenster.",
	["Give a group channel its own window. The messenger never posts by itself: a line goes out only when you press Enter in the window."] = "Gebt einem Gruppenkanal ein eigenes Fenster. Der Messenger postet nie von selbst: Eine Zeile geht nur hinaus, wenn Ihr im Fenster die Eingabetaste drückt.",
	["Give a quest ID, or open a quest first."] = "Gebt eine Quest-ID an oder öffnet zuerst eine Quest.",
	["Give coordinates, like /way 45.2 63.8 or /way Elwynn Forest 45 63 Goldshire."] = "Gebt Koordinaten an, etwa /way 45.2 63.8 oder /way Wald von Elwynn 45 63 Goldhain.",
	["Give the chosen snapshot a name, so it is easy to find in the list."] = "Gebt dem gewählten Schnappschuss einen Namen, damit er in der Liste leicht zu finden ist.",
	["Give the health bar the color below."] = "Der Gesundheitsleiste die Farbe unten geben.",
	["Give the name the color below."] = "Dem Namen die Farbe unten geben.",
	["Give the plate border the color below (the target highlight still wins)."] = "Dem Plakettenrand die Farbe unten geben (die Zielhervorhebung hat weiterhin Vorrang).",
	["Give the tooltip shadow its own strength and size. Off follows Frame shadows on Global settings > Textures."] = "Dem Tooltipschatten eine eigene Stärke und Größe geben. Aus folgt Rahmenschatten unter Globale Einstellungen > Texturen.",
	["Give this frame its own frame art. Like all frames uses the Unit-frame graphics row at the top of this tab. Frames lower than 40 pixels get a thin edge in place of the full border."] = "Diesem Rahmen eine eigene Rahmengrafik geben. Die Einstellung Wie alle Rahmen nutzt die Zeile Einheitenrahmen-Grafiken oben auf diesem Reiter. Rahmen unter 40 Pixel Höhe erhalten statt des vollen Rands eine dünne Kante.",
	["Gives every raid member assistant rights, or takes them back (raid leader). The border turns accent while it is on."] = "Gibt jedem Schlachtzugsmitglied Assistentenrechte oder nimmt sie wieder (Schlachtzugsleiter). Der Rand nimmt die Akzentfarbe an, solange es an ist.",
	["Gives every raid member assistant rights, or takes them back."] = "Gibt jedem Schlachtzugsmitglied Assistentenrechte oder nimmt sie wieder.",
	["Gives the active scale the name above."] = "Gibt der aktiven Gewichtung den Namen oben.",
