	["Hide in instances"] = "In Instanzen ausblenden",
	["Hide in raids"] = "In Schlachtzügen ausblenden",
	["Hide it completely (no voice), or hide only the frame and still hear the voice."] = "Ganz ausblenden (keine Stimme) oder nur den Rahmen ausblenden und die Stimme weiter hören.",
	["Hide items below this quality."] = "Gegenstände unter dieser Qualität ausblenden.",
	["Hide out of combat"] = "Außerhalb des Kampfes ausblenden",
	["Hide plates behind the camera"] = "Plaketten hinter der Kamera ausblenden",
	["Hide red errors by category, in combat, or always. Yellow quest progress always shows."] = "Rote Fehler nach Kategorie, im Kampf oder immer ausblenden. Gelber Questfortschritt wird immer angezeigt.",
	["Hide the PvP line"] = "PvP-Zeile ausblenden",
	["Hide the Shop micro button"] = "Shop-Mikroschaltfläche ausblenden",
	["Hide the alert types checked below."] = "Die unten angehakten Hinweisarten ausblenden.",
	["Hide the arrow"] = "Pfeil ausblenden",
	["Hide the bar for spells the game does not mark as important, so only the casts that matter show."] = "Die Leiste bei Zaubern ausblenden, die das Spiel nicht als wichtig markiert, damit nur die Zauber erscheinen, auf die es ankommt.",
	["Hide the bar while the cast can't be interrupted. The game decides; the client sets the bar's visibility, EldoUI never reads the answer."] = "Die Leiste ausblenden, solange der Zauber nicht unterbrochen werden kann. Das Spiel entscheidet; der Client setzt die Sichtbarkeit der Leiste, EldoUI liest die Antwort nie.",
	["Hide the encounter bar"] = "Begegnungsleiste ausblenden",
	["Hide the faction line"] = "Fraktionszeile ausblenden",
	["Hide the four bag slots; the backpack button stays."] = "Die vier Taschenplätze ausblenden; die Rucksackschaltfläche bleibt.",
	["Hide the game's own totem bar and totem timers while this bar is on, so there is one totem bar."] = "Die eigene Totemleiste und die Totemtimer des Spiels ausblenden, solange diese Leiste an ist, damit es nur eine Totemleiste gibt.",
	["Hide the other faction's flight masters, docks and towers. Neutral ones always show."] = "Flugmeister, Anleger und Türme der anderen Fraktion ausblenden. Neutrale werden immer angezeigt.",
	["Hide the other faction's services. Neutral towns, and NPCs whose side the data can't tell, always show."] = "Dienste der anderen Fraktion ausblenden. Neutrale Orte und NSCs, deren Seite die Daten nicht kennen, werden immer angezeigt.",
	["Hide the plate"] = "Plakette ausblenden",
	["Hide them"] = "Ausblenden",
	["Hide these types"] = "Diese Typen ausblenden",
	["Hide this point"] = "Diesen Punkt ausblenden",
	["Hide top-center widgets"] = "Widgets oben in der Mitte ausblenden",
	["Hide what"] = "Was ausblenden",
	["Hide what you already know"] = "Bereits Bekanntes ausblenden",
	["Hide your own and friendly names"] = "Eigenen und freundliche Namen ausblenden",
	["Hide: %s"] = "Ausblenden: %s",
	["Hides \"X has defeated Y in a duel\" system messages."] = "Blendet Systemmeldungen „X hat Y in einem Duell besiegt“ aus.",
	["Hides <Right Click to Open>, <Right Click to Read> and <Shift Right Click to Socket>."] = "Blendet <Rechtsklick zum Öffnen>, <Rechtsklick zum Lesen> und <Umschalt-Rechtsklick zum Sockeln> aus.",
	["Hides Blizzard's own item level line while the info area shows it, so it appears once."] = "Blendet Blizzards eigene Zeile zur Gegenstandsstufe aus, solange der Infobereich sie zeigt, damit sie nur einmal erscheint.",
	["Hides names in what EldoUI draws: unit, group and nameplate texts, tooltips and chat senders. Other frames keep the real names."] = "Blendet Namen in allem aus, was EldoUI zeichnet: Texte von Einheitenrahmen, Gruppenrahmen und Namensplaketten, Tooltips und Chatabsender. Andere Rahmen behalten die echten Namen.",
	["Hides other players' \"X seems a little tipsy\" messages."] = "Blendet Meldungen anderer Spieler wie „X scheint etwas beschwipst zu sein“ aus.",
	["Hides the crafter and gift-wrap lines (matched by the game's own text)."] = "Blendet die Zeilen zu Hersteller und Geschenkverpackung aus (erkannt am eigenen Text des Spiels).",
	["Hides the names over characters in the world through the game's own name settings while Streamer Mode is on, and puts your settings back when it goes off. Off by default (Game setting)."] = "Blendet die Namen über Charakteren in der Welt über die eigenen Namenseinstellungen des Spiels aus, solange der Streamermodus an ist, und stellt Eure Einstellungen wieder her, wenn er ausgeht. Standardmäßig aus (Spieleinstellung).",
	["Higher in the list: this rule wins over the ones below."] = "Weiter oben in der Liste: Diese Regel hat Vorrang vor denen darunter.",
	["Higher rank known"] = "Höherer Rang bekannt",
	["Higher rank known (%d > %d)"] = "Höherer Rang bekannt (%d > %d)",
	["Higher rank known (preview)"] = "Höherer Rang bekannt (Vorschau)",
	["Higher zooms faster; the game's default is 20 (game setting)."] = "Höher zoomt schneller; der Standard des Spiels ist 20 (Spieleinstellung).",
	["Highest known rank"] = "Höchster bekannter Rang",
	["Highest unit level."] = "Höchste Einheitenstufe.",
	["Highlight in the accent color"] = "In der Akzentfarbe hervorheben",
	["Highlight your name"] = "Euren Namen hervorheben",
	["Highlight your soft target"] = "Euer weiches Ziel hervorheben",
	["History"] = "Verlauf",
	["History browser"] = "Verlaufsbrowser",
	["HoT/s"] = "HoT/s",
	["Hold Alt and right-click on the world map to add your own note there. While HandyNotes is loaded, its own Alt+right-click is used instead."] = "Haltet Alt gedrückt und klickt mit rechts auf die Weltkarte, um dort eine eigene Notiz hinzuzufügen. Solange HandyNotes geladen ist, wird stattdessen dessen eigener Alt-Rechtsklick genutzt.",
	["Hold Ctrl and right-click on the world map to add a waypoint there."] = "Haltet Strg gedrückt und klickt mit rechts auf die Weltkarte, um dort einen Wegpunkt zu setzen.",
	["Hold Shift for node types"] = "Umschalt halten für Vorkommensarten",
	["Hold Shift over a zone to list its herbs and ore veins: your own finds when the Gathering module knows the zone, else the nodes that typically grow there."] = "Haltet Umschalt über einem Gebiet, um seine Kräuter und Erzadern aufzulisten: Eure eigenen Funde, wenn das Modul Sammeln das Gebiet kennt, sonst die Vorkommen, die dort üblicherweise wachsen.",
	["Hold Shift to see what the values come from: the average, the part over time, the time used and the mana cost."] = "Haltet Umschalt, um zu sehen, woraus sich die Werte ergeben: der Durchschnitt, der Anteil über Zeit, die benötigte Zeit und die Manakosten.",
	["Hold a key for a ring, fan or grid of your own spells, items, macros, mounts and markers; let go on one to use it."] = "Haltet eine Taste für einen Ring, Fächer oder ein Raster aus Euren eigenen Zaubern, Gegenständen, Makros, Reittieren und Markierungen; lasst über einem Eintrag los, um ihn zu benutzen.",
	["Hold a menu's key to show its entries around the cursor; point at one and let go to use it. Escape cancels. Works in combat."] = "Haltet die Taste eines Menüs, um seine Einträge um den Cursor anzuzeigen; zeigt auf einen und lasst los, um ihn zu benutzen. Esc bricht ab. Funktioniert im Kampf.",
	["Hold this key while casting a helpful spell to cast it on yourself (the game's key binding setting)."] = "Haltet diese Taste beim Wirken eines hilfreichen Zaubers, um ihn auf Euch selbst zu wirken (Tastenbelegungseinstellung des Spiels).",
	["Hold this key while talking to an NPC to stop the quest helpers."] = "Haltet diese Taste im Gespräch mit einem NSC, um die Questhelfer anzuhalten.",
	["Hold time"] = "Haltezeit",
	["Hold to pause"] = "Halten zum Pausieren",
	["Hold to show in combat"] = "Halten zum Anzeigen im Kampf",
	["Holding this key shows hidden tooltips anyway."] = "Wird diese Taste gehalten, erscheinen ausgeblendete Tooltips trotzdem.",
	["Holds the item of your tracked quest. Bind a key to it in keybind mode."] = "Enthält den Gegenstand Eurer verfolgten Quest. Belegt ihn im Tastenbelegungsmodus mit einer Taste.",
	["Honor bar"] = "Ehreleiste",
	["Honor color"] = "Ehrefarbe",
	["Hop canceled."] = "Wechsel abgebrochen.",
	["Hop to another layer"] = "Zu einem anderen Layer wechseln",
	["Hop to layer %s"] = "Zu Layer %s wechseln",
	["Hopping"] = "Layerwechsel",
	["Horizontal distance from the cursor."] = "Horizontaler Abstand zum Cursor.",
	["Horizontal shift from the frame's right edge."] = "Horizontale Verschiebung vom rechten Rand des Rahmens.",
	["Horizontal shift in pixels."] = "Horizontale Verschiebung in Pixeln.",
	["Horizontal shift of a free icon."] = "Horizontale Verschiebung eines freien Symbols.",
	["Horizontal shift of the combat icon."] = "Horizontale Verschiebung des Kampfsymbols.",
	["Horizontal shift of the resting icon."] = "Horizontale Verschiebung des Erholungssymbols.",
	["Horizontal shift of the stack count."] = "Horizontale Verschiebung der Stapelanzahl.",
	["Horizontal shift of the time."] = "Horizontale Verschiebung der Zeit.",
	["Horizontal shift."] = "Horizontale Verschiebung.",
	["Hostile units, with own colors for nameplates."] = "Feindselige Einheiten, mit eigenen Farben für Namensplaketten.",
	["Hostile, neutral and friendly"] = "Feindselig, neutral und freundlich",
	["Housing"] = "Behausung",
	["Hover a cast bar for the spell's tooltip; a mob's tooltip lists the abilities it cast in front of you and where reputation tokens go."] = "Zeigt auf eine Zauberleiste für den Tooltip des Zaubers; der Tooltip eines Gegners listet die Fähigkeiten, die er vor Euch gewirkt hat, und wohin Rufmarken gehören.",
	["Hover a zone on a continent map for its level range, gathering ranges, dungeons and territory. Hold Shift for its node types."] = "Zeigt auf einer Kontinentkarte auf ein Gebiet für seinen Stufenbereich, seine Sammelbereiche, Dungeons und sein Territorium. Haltet Umschalt für seine Vorkommensarten.",
	["Hover an item, spell, quest or creature (or target a creature), then type /eui wowhead. Ctrl+Alt-click works on chat links."] = "Zeigt auf einen Gegenstand, einen Zauber, eine Quest oder eine Kreatur (oder nehmt eine Kreatur ins Ziel) und gebt dann /eui wowhead ein. Strg+Alt-Klick funktioniert bei Chatlinks.",
	["Hover any EldoUI button and press a key. Out of combat only."] = "Zeigt auf eine beliebige EldoUI-Schaltfläche und drückt eine Taste. Nur außerhalb des Kampfes.",
	["Hover one of EldoUI's cooldown icons and press your ping key: the game pings that spell or item, as it does for Blizzard's Cooldown Manager. One key press, one ping."] = "Zeigt auf eines der Abklingzeitsymbole von EldoUI und drückt Eure Ping-Taste: Das Spiel pingt diesen Zauber oder Gegenstand, wie beim Abklingzeitenmanager von Blizzard. Ein Tastendruck, ein Ping.",
	["Hover the quest item button and press a key, then click Save."] = "Zeigt auf die Questgegenstand-Schaltfläche, drückt eine Taste und klickt dann auf Speichern.",
	["How a missing (red) reminder draws the eye. Glow uses the Reminders row on the Glows page."] = "Wie eine fehlende (rote) Erinnerung den Blick auf sich zieht. Leuchten nutzt die Zeile Erinnerungen auf der Seite „Leuchteffekte“.",
	["How close, in yards, counts as arrived."] = "Wie nah, in Metern, als angekommen gilt.",
	["How dark the panel is. 0.9 matches the game's own tooltips."] = "Wie dunkel das Panel ist. 0.9 entspricht den Tooltips des Spiels.",
	["How dark the tooltip shadow is."] = "Wie dunkel der Tooltipschatten ist.",
	["How dark the world behind the flight view gets."] = "Wie dunkel die Welt hinter der Flugansicht wird.",
	["How detailed the volume fog is. Lower is faster."] = "Wie detailliert der Volumennebel ist. Niedriger ist schneller.",
	["How early you can queue your next spell before the current cast or global cooldown ends (\"lag tolerance\"). Off keeps the game's value (now %s ms)."] = "Wie früh Ihr Euren nächsten Zauber vormerken könnt, bevor der aktuelle Zauber oder die globale Abklingzeit endet („Lagtoleranz“). Aus behält den Wert des Spiels (jetzt %s ms).",
	["How every gain in EldoUI is worked out for this character: your stat weights, or another rating mode an add-on provides (such as the Loot Guide's simulator)."] = "Wie jeder Zugewinn in EldoUI für diesen Charakter berechnet wird: Eure Wertgewichte oder ein anderer Bewertungsmodus, den ein Add-on bereitstellt (etwa der Simulator des Loot Guide).",
	["How far the camera can zoom out (game setting): now about %d yd. The range follows what this client allows."] = "Wie weit die Kamera herauszoomen kann (Spieleinstellung): jetzt etwa %d m. Der Bereich richtet sich danach, was dieser Client erlaubt.",
	["How far the camera sits to the side of your character; below 0 is the left shoulder."] = "Wie weit seitlich die Kamera neben Eurem Charakter sitzt; unter 0 ist die linke Schulter.",
	["How far the tooltip shadow reaches beyond its edge."] = "Wie weit der Tooltipschatten über seinen Rand hinausreicht.",
	["How fast the camera tilts up and down when you drag with the mouse (game setting cameraPitchMoveSpeed)."] = "Wie schnell die Kamera nach oben und unten kippt, wenn Ihr mit der Maus zieht (Spieleinstellung cameraPitchMoveSpeed).",
	["How fast the camera turns left and right when you drag with the mouse (game setting cameraYawMoveSpeed)."] = "Wie schnell sich die Kamera nach links und rechts dreht, wenn Ihr mit der Maus zieht (Spieleinstellung cameraYawMoveSpeed).",
	["How fast the numbers over targets fall after they appear. 0 lets them float (game setting WorldTextGravity)."] = "Wie schnell die Zahlen über Zielen fallen, nachdem sie erscheinen. 0 lässt sie schweben (Spieleinstellung WorldTextGravity).",
	["How high the frame sits among other bars. Raise it when another frame covers it. The game menu, the settings and popups always stay on top."] = "Wie hoch der Rahmen unter anderen Leisten liegt. Erhöht den Wert, wenn ein anderer Rahmen ihn verdeckt. Spielmenü, Einstellungen und Pop-ups bleiben immer obenauf.",
	["How long a battleground message stays before it fades."] = "Wie lange eine Schlachtfeldmeldung stehen bleibt, bevor sie verblasst.",
	["How long a message stays; 0 keeps Blizzard's time."] = "Wie lange eine Meldung stehen bleibt; 0 behält Blizzards Zeit.",
	["How long a toast stays. Hovering it keeps it; right-click closes it."] = "Wie lange ein Hinweis stehen bleibt. Zeigt Ihr darauf, bleibt er; Rechtsklick schließt ihn.",
	["How long before the same rare alerts again."] = "Wie lange es dauert, bis derselbe rare Gegner erneut gemeldet wird.",
	["How long the interrupted strip stays."] = "Wie lange der Unterbrochen-Streifen stehen bleibt.",
	["How long the panel stays open after the ready check ends."] = "Wie lange das Panel nach dem Bereitschaftscheck geöffnet bleibt.",
	["How long until you arrive at your current speed towards it."] = "Wie lange es bei Eurer aktuellen Geschwindigkeit dauert, bis Ihr dort ankommt.",
	["How many"] = "Wie viele",
	["How many %s? (sold in lots of %d)"] = "Wie viele %s? (verkauft in Einheiten zu %d)",
	["How many Runes of Teleportation and Runes of Portals you carry: on the button and under each row. A kind you have none of is grayed out."] = "Wie viele Runen der Teleportation und Runen der Portale Ihr dabeihabt: auf der Schaltfläche und unter jeder Zeile. Eine Sorte, von der Ihr keine habt, ist ausgegraut.",
	["How many abilities the row names before it shows (+N)."] = "Wie viele Fähigkeiten die Zeile nennt, bevor sie (+N) zeigt.",
	["How many automatic snapshots to keep per character; the oldest go first. Your own snapshots are kept (up to 20)."] = "Wie viele automatische Schnappschüsse pro Charakter behalten werden; die ältesten gehen zuerst. Eure eigenen Schnappschüsse bleiben erhalten (bis zu 20).",
	["How many buttons before a new row starts."] = "Wie viele Schaltflächen, bevor eine neue Reihe beginnt.",
	["How many cells per row."] = "Wie viele Zellen pro Reihe.",
	["How many conversations the dock shows. Right-click a dock button to close that conversation."] = "Wie viele Unterhaltungen das Dock zeigt. Rechtsklick auf eine Dock-Schaltfläche schließt diese Unterhaltung.",
	["How many lines of tiles before it scrolls. Columns times rows is how many items you see at once."] = "Wie viele Kachelreihen, bevor gescrollt wird. Spalten mal Reihen ergibt, wie viele Gegenstände Ihr auf einmal seht.",
	["How many mobs show before \"+N more\". Hold Shift for the full list."] = "Wie viele Gegner erscheinen, bevor „+N weitere“ folgt. Haltet Umschalt für die ganze Liste.",
	["How many names a line lists before \"+N more\"."] = "Wie viele Namen eine Zeile vor „+N weitere“ auflistet.",
	["How many of a reagent you have and need for the recipes you pinned in the Profession Planner."] = "Wie viel Ihr von einem Reagenz habt und für die Rezepte braucht, die Ihr im Berufsplaner angeheftet habt.",
	["How many of the chosen food you carry."] = "Wie viel vom gewählten Futter Ihr dabeihabt.",
	["How many of the item you carry, in the corner of its icon."] = "Wie viele Exemplare des Gegenstands Ihr dabeihabt, in der Ecke seines Symbols.",
	["How many of the mob's most common drops to list."] = "Wie viele der häufigsten Beutestücke des Gegners aufgelistet werden.",
	["How many pings the feed shows; the newest is on top."] = "Wie viele Pings der Ticker zeigt; der neueste steht oben.",
	["How many points the path plans, of the 51 a level 60 character has."] = "Wie viele der 51 Punkte eines Charakters der Stufe 60 der Pfad verplant.",
	["How many recipients the address book keeps under Recent."] = "Wie viele Empfänger das Adressbuch unter Kürzlich behält.",
	["How many skills you can learn right now and what they cost together. You still train each one yourself."] = "Wie viele Fertigkeiten Ihr gerade erlernen könnt und was sie zusammen kosten. Jede erlernt Ihr weiterhin selbst.",
	["How many tiles side by side."] = "Wie viele Kacheln nebeneinander.",
	["How many times the notable sound plays."] = "Wie oft der Ton für bemerkenswerte Funde abgespielt wird.",
	["How many times the sound plays."] = "Wie oft der Ton abgespielt wird.",
	["How many trades the log keeps; the oldest go first."] = "Wie viele Handelsvorgänge das Protokoll behält; die ältesten gehen zuerst.",
	["How many uses the item has left, when more than one."] = "Wie viele Anwendungen der Gegenstand noch hat, wenn es mehr als eine ist.",
	["How much ammo to keep when you carry no quiver or ammo pouch. Never buys past this amount."] = "Wie viel Munition Ihr behaltet, wenn Ihr keinen Köcher und keinen Munitionsbeutel tragt. Kauft nie über diese Menge hinaus.",
	["How much of the 3D model the camera shows."] = "Wie viel vom 3D-Modell die Kamera zeigt.",
	["How much of the circle the entries use. 360 is a full ring; less makes an arc."] = "Wie viel vom Kreis die Einträge nutzen. 360 ist ein voller Ring; weniger ergibt einen Bogen.",
	["How party and raid members are named. A member without a role or class shown falls back to Party or Raid and a number. \"Only your own aliases\" renames only the characters on your alias list."] = "Wie Gruppen- und Schlachtzugsmitglieder benannt werden. Ein Mitglied ohne angezeigte Rolle oder Klasse wird zu Gruppe oder Schlachtzug und einer Nummer. „Nur Eure eigenen Aliasnamen“ benennt nur die Charaktere auf Eurer Aliasliste um.",
	["How plates other than your target step back while you have one: lower opacity, or a dark overlay that keeps names readable."] = "Wie Plaketten außer Eurem Ziel zurücktreten, während Ihr eines habt: geringere Deckkraft oder eine dunkle Überlagerung, die Namen lesbar hält.",
	["How prices are written. \"Use general setting\" follows Fonts and text > Money."] = "Wie Preise geschrieben werden. „Allgemeine Einstellung verwenden“ folgt Schriften und Text > Geld.",
	["How see-through the pins are."] = "Wie durchsichtig die Markierungen sind.",
	["How see-through the transport pins are."] = "Wie durchsichtig die Transportmarkierungen sind.",
	["How solid the bar looks."] = "Wie deckend die Leiste aussieht.",
	["How strong the portrait shows over the health bar."] = "Wie stark das Porträt über der Gesundheitsleiste erscheint.",
	["How strong the pulse is."] = "Wie stark das Pulsieren ist.",
	["How strongly the unexplored areas show: low values are faint."] = "Wie stark die unerkundeten Bereiche erscheinen: Niedrige Werte sind blass.",
	["How tall the tracker may grow. Quests that don't fit are cut off, as in Blizzard's tracker."] = "Wie hoch die Verfolgung werden darf. Quests, die nicht hineinpassen, werden abgeschnitten, wie in Blizzards Verfolgung.",
	["How the amounts are written. \"Use general setting\" follows Fonts and text > Money."] = "Wie die Beträge geschrieben werden. „Allgemeine Einstellung verwenden“ folgt Schriften und Text > Geld.",
	["How the cast time reads."] = "Wie die Zauberzeit angezeigt wird.",
	["How the text lines up. From the position: left on the left side, right on the right side."] = "Wie der Text ausgerichtet ist. Nach Position: links auf der linken Seite, rechts auf der rechten Seite.",
	["How the time left shows. Numbers and text are drawn by the game from a time EldoUI never reads."] = "Wie die Restzeit angezeigt wird. Zahlen und Text zeichnet das Spiel aus einer Zeit, die EldoUI nie liest.",
	["How the toast appears. Animations follow the General page's animation setting."] = "Wie der Hinweis erscheint. Animationen folgen der Animationseinstellung auf der Seite Allgemein.",
	["How the toast arranges the zone name and its details."] = "Wie der Hinweis den Gebietsnamen und seine Details anordnet.",
	["How the unit stands towards you."] = "Wie die Einheit zu Euch steht.",
	["How thick rain and snow are. \"Game setting\" puts your own value back."] = "Wie dicht Regen und Schnee sind. „Spieleinstellung“ stellt Euren eigenen Wert wieder her.",
	["How your target's plate is marked."] = "Wie die Plakette Eures Ziels markiert wird.",
	["Hunters: Feed Pet button next to the pet frame, unhappy pet and low food warnings."] = "Jäger: Schaltfläche Tier füttern neben dem Tierrahmen, Warnungen bei unzufriedenem Tier und wenig Futter.",
	["Hunters: no pet (Call Pet on click). Warlocks: no demon, or a demon you did not allow below."] = "Jäger: kein Tier (Tier rufen per Klick). Hexenmeister: kein Dämon oder ein Dämon, den Ihr unten nicht erlaubt habt.",
	["IM: the box stays under the chat"] = "IM: Das Eingabefeld bleibt unter dem Chat",
	["Icon X offset"] = "Symbol-X-Versatz",
	["Icon Y offset"] = "Symbol-Y-Versatz",
	["Icon picked. Save to keep it."] = "Symbol gewählt. Speichert, um es zu behalten.",
	["Icon placement"] = "Symbolplatzierung",
	["Icon side"] = "Symbolseite",
	["Icon size of the private auras."] = "Symbolgröße der privaten Auren.",
	["Icons and names, five before more, times seen in the Shift list, your standing on tokens."] = "Symbole und Namen, fünf vor weiteren, Sichtungen in der Umschalt-Liste, Euer Rufstand bei Marken.",
	["Icons for key spells, lit while they are off cooldown and dim while it runs. Off by default."] = "Symbole für wichtige Zauber, hell, solange sie keine Abklingzeit haben, und gedimmt, während sie läuft. Standardmäßig aus.",
	["Icons in one row before the next row starts."] = "Symbole in einer Reihe, bevor die nächste Reihe beginnt.",
	["Icons over things you can use"] = "Symbole über benutzbaren Dingen",
	["Icons with a countdown, or one timer bar per aura with its name."] = "Symbole mit Countdown oder eine Timerleiste pro Aura mit ihrem Namen.",
	["Icons, colored group titles, striped rows."] = "Symbole, farbige Gruppentitel, gestreifte Zeilen.",
	["Icons: the game's flight master art and a shape per kind. Colored dots: small dots. High contrast: large outlined shapes. Forever bronze: bronze shapes. Minimal: faint dots."] = "Symbole: die Flugmeistergrafik des Spiels und eine Form pro Art. Farbige Punkte: kleine Punkte. Hoher Kontrast: große Formen mit Kontur. Forever-Bronze: bronzene Formen. Minimal: blasse Punkte.",
	["If your gold is short, the repair happens when you get the money while the vendor is still open."] = "Reicht Euer Gold nicht, wird repariert, sobald Ihr das Geld habt, solange der Händler noch offen ist.",
	["Ignore"] = "Ignorieren",
	["Ignore %s?"] = "%s ignorieren?",
	["Ignore tab"] = "Reiter Ignorieren",
	["Ignore this event"] = "Dieses Ereignis ignorieren",
	["Ignore this rare"] = "Diesen raren Gegner ignorieren",
	["Ignore this rare, open it in the Loot Guide or show it on the map."] = "Diesen raren Gegner ignorieren, im Loot Guide öffnen oder auf der Karte zeigen.",
	["Ignore this treasure"] = "Diesen Schatz ignorieren",
	["Ignored"] = "Ignoriert",
	["Ignored spells"] = "Ignorierte Zauber",
	["Imbue"] = "Waffenverzauberung",
	["Imbue %s"] = "Verzauberung %s",
	["Imbue %s / %s"] = "Verzauberung %s / %s",
	["Import TMB"] = "TMB importieren",
	["Import a loadout"] = "Zusammenstellung importieren",
	["Import a softres.it or That's My BiS export to see who wants which item."] = "Importiert einen Export von softres.it oder That's My BiS, um zu sehen, wer welchen Gegenstand will.",
	["Import a talent plan"] = "Talentplan importieren",
	["Import build"] = "Build importieren",
	["Import nameplate style filters"] = "Stilfilter für Namensplaketten importieren",
	["Import reserve lists to see them on tooltips and loot rolls. The ledger only keeps numbers: you roll, trade and pay out yourself."] = "Importiert Reservierungslisten, um sie in Tooltips und bei Beutewürfen zu sehen. Das Kassenbuch hält nur Zahlen fest: Würfeln, Handeln und Auszahlen erledigt Ihr selbst.",
	["Import rules"] = "Regeln importieren",
	["Import soft reserves"] = "Soft-Reserves importieren",
	["Important (Blizzard)"] = "Wichtig (Blizzard)",
	["Imported %d entries."] = { one = "%d Eintrag importiert.", other = "%d Einträge importiert." },
	["Imported a Pawn scale with %d stats."] = "Pawn-Gewichtung mit %d Werten importiert.",
	["Imported a scale with %d stats."] = "Gewichtung mit %d Werten importiert.",
	["Importing only saves it; the restore window then shows every change and waits for your click."] = "Importieren speichert ihn nur; das Wiederherstellungsfenster zeigt dann jede Änderung und wartet auf Euren Klick.",
	["In"] = "Erhalten",
	["In PvP"] = "Im PvP",
	["In a group"] = "In einer Gruppe",
	["In a group, a small panel shows the quests you share with your party and the ones only you or they have. Share and Ask are one click each."] = "In einer Gruppe zeigt ein kleines Panel die Quests, die Ihr mit Eurer Gruppe teilt, und die, die nur Ihr oder nur sie habt. Teilen und Fragen sind je ein Klick.",
	["In a group, a totem button's tooltip names the members its buff doesn't reach (out of combat)."] = "In einer Gruppe nennt der Tooltip einer Totemschaltfläche die Mitglieder, die sein Stärkungszauber nicht erreicht (außerhalb des Kampfes).",
	["In a group, only units in the healer role show a power bar."] = "In einer Gruppe zeigen nur Einheiten in der Heilerrolle eine Ressourcenleiste.",
	["In arenas"] = "In Arenen",
	["In battlegrounds"] = "Auf Schlachtfeldern",
	["In combat: keep writing, Save waits until combat ends."] = "Im Kampf: Schreibt weiter, Speichern wartet bis zum Kampfende.",
	["In combat: restore after combat."] = "Im Kampf: nach dem Kampf wiederherstellen.",
	["In combat: the menus work, edits wait until combat ends."] = "Im Kampf: Die Menüs funktionieren, Änderungen warten bis zum Kampfende.",
	["In dungeons"] = "In Dungeons",
	["In dungeons and raids with a warlock in the group who can make one (or when you can): a note when you carry no Healthstone."] = "In Dungeons und Schlachtzügen mit einem Hexenmeister in der Gruppe, der einen herstellen kann (oder wenn Ihr es könnt): ein Hinweis, wenn Ihr keinen Gesundheitsstein dabeihabt.",
	["In dungeons and raids, out of combat, while nobody in the group has a Soulstone and yours is ready: a click puts it on the group's healer."] = "In Dungeons und Schlachtzügen, außerhalb des Kampfes, solange niemand in der Gruppe einen Seelenstein hat und Eurer bereit ist: Ein Klick legt ihn auf den Heiler der Gruppe.",
	["In execute range"] = "Im Hinrichtungsbereich",
