	["Item"] = "Gegenstand",
	["Item #%s"] = "Gegenstand #%s",
	["Item ID"] = "Gegenstands-ID",
	["Item IDs, names or links of non-gray items to sell as junk too, separated by commas. Empty by default."] = "Gegenstands-IDs, Namen oder Links nicht grauer Gegenstände, die ebenfalls als Plunder verkauft werden, durch Kommas getrennt. Standardmäßig leer.",
	["Item IDs, names or links, separated by commas. Protects a gray item from being sold."] = "Gegenstands-IDs, Namen oder Links, durch Kommas getrennt. Schützt einen grauen Gegenstand vor dem Verkauf.",
	["Item Level"] = "Gegenstandsstufe",
	["Item count"] = "Gegenstandsanzahl",
	["Item icons"] = "Gegenstandssymbole",
	["Item level and IDs"] = "Gegenstandsstufe und IDs",
	["Item level of gear in the info area."] = "Gegenstandsstufe der Ausrüstung im Infobereich.",
	["Item level on gear (moved out of Blizzard's lines), a player's item level, and the item ID as set below."] = "Gegenstandsstufe auf Ausrüstung (aus Blizzards Zeilen herausgenommen), die Gegenstandsstufe eines Spielers und die Gegenstands-ID wie unten eingestellt.",
	["Item levels on slots"] = "Gegenstandsstufen auf Plätzen",
	["Item list"] = "Gegenstandsliste",
	["Item list beside the window"] = "Gegenstandsliste neben dem Fenster",
	["Item name, ID or link, or drop an item"] = "Gegenstandsname, ID oder Link, oder legt einen Gegenstand ab",
	["Item names are still loading. Try again in a moment."] = "Gegenstandsnamen werden noch geladen. Versucht es gleich noch einmal.",
	["Item quality for items, class or reaction for units."] = "Gegenstandsqualität bei Gegenständen, Klasse oder Reaktion bei Einheiten.",
	["Item slots as flat boxes with an item quality border."] = "Gegenstandsplätze als flache Felder mit Rand in Gegenstandsqualität.",
	["Item tooltips"] = "Gegenstandstooltips",
	["Item tooltips always show what you wear in that slot beside them, without holding Shift (game setting)."] = "Gegenstandstooltips zeigen immer daneben, was Ihr in diesem Platz tragt, ohne dass Ihr Umschalt haltet (Spieleinstellung).",
	["Item: drop, shift-click or type"] = "Gegenstand: ablegen, Umschaltklick oder eingeben",
	["Items and spells"] = "Gegenstände und Zauber",
	["Items below this quality are left out (or faded) when a vendor opens."] = "Gegenstände unter dieser Qualität werden beim Öffnen eines Händlers weggelassen (oder abgeblendet).",
	["Items from loot windows and rolls in your group this session."] = "Gegenstände aus Beutefenstern und Würfen in Eurer Gruppe in dieser Sitzung.",
	["Items that don't match"] = "Nicht passende Gegenstände",
	["Items won from rolls and loot upgrades."] = "Bei Würfen gewonnene Gegenstände und Beuteverbesserungen.",
	["Items you won from a roll. Off by default: the Loot module shows loot toasts."] = "Gegenstände, die Ihr bei einem Wurf gewonnen habt. Standardmäßig aus: Das Modul Beute zeigt Beutehinweise.",
	["Its cooldown and how many Ankhs you carry."] = "Seine Abklingzeit und wie viele Ankhs Ihr dabeihabt.",
	["Its cooldown; click to cast it."] = "Seine Abklingzeit; klickt, um ihn zu wirken.",
	["JPG"] = "JPG",
	["Join a group with a shaman to see the group's shaman cooldowns."] = "Tretet einer Gruppe mit einem Schamanen bei, um die Schamanen-Abklingzeiten der Gruppe zu sehen.",
	["Join a group, or start a ready check, to see who is missing what."] = "Tretet einer Gruppe bei oder startet einen Bereitschaftscheck, um zu sehen, wem was fehlt.",
	["Join the layer network"] = "Dem Layer-Netzwerk beitreten",
	["Join the layer network or a guild first."] = "Tretet zuerst dem Layer-Netzwerk oder einer Gilde bei.",
	["Joins a hidden chat channel that players of EldoUI and of the layer addon share, so you can ask them for a hop and help them. It never shows in your chat. Off: hops go through your guild only."] = "Tritt einem versteckten Chatkanal bei, den Spieler von EldoUI und des Layer-Addons teilen, damit Ihr sie um einen Wechsel bitten und ihnen helfen könnt. Er erscheint nie in Eurem Chat. Aus: Wechsel laufen nur über Eure Gilde.",
	["Journal"] = "Tagebuch",
	["Journal line on tooltips"] = "Tagebuchzeile in Tooltips",
	["Junk"] = "Plunder",
	["Junk rules"] = "Plunderregeln",
	["Junk selling skips items an open quest needs, items that start a quest you haven't done, and recipes one of your characters can still learn. On by default."] = "Der Plunderverkauf überspringt Gegenstände, die eine offene Quest braucht, Gegenstände, die eine noch nicht erledigte Quest starten, und Rezepte, die einer Eurer Charaktere noch lernen kann. Standardmäßig an.",
	["Just the name in class or reaction color, no bar."] = "Nur der Name in Klassen- oder Reaktionsfarbe, keine Leiste.",
	["Just the time and the difference, no labels, no total, no panel."] = "Nur die Zeit und die Differenz, keine Beschriftungen, keine Summe, kein Panel.",
	["Just the totem bar: no cooldown bar, no key labels, no edges."] = "Nur die Totemleiste: keine Abklingzeitleiste, keine Tastenbeschriftungen, keine Ränder.",
	["Just the world markers, for anyone who places them."] = "Nur die Weltmarkierungen, für alle, die sie setzen.",
	["Keep        In bags"] = "Behalten    In Taschen",
	["Keep Blizzard's pet cast bar."] = "Blizzards Zauberleiste des Begleiters behalten.",
	["Keep Blizzard's totem timers"] = "Blizzards Totemtimer behalten",
	["Keep a log of sent mail"] = "Protokoll gesendeter Post führen",
	["Keep a snapshot whenever your bars, macros, keys or Edit Mode layout changed since the last one."] = "Einen Schnappschuss anlegen, wann immer sich Eure Leisten, Makros, Tasten oder das Layout des Bearbeitungsmodus seit dem letzten geändert haben.",
	["Keep a trade log"] = "Handelsprotokoll führen",
	["Keep bag slots free"] = "Taschenplätze freihalten",
	["Keep between sessions"] = "Zwischen Sitzungen behalten",
	["Keep editing"] = "Weiter bearbeiten",
	["Keep filters between vendors"] = "Filter zwischen Händlern behalten",
	["Keep group lines in the history too. Off keeps only whispers."] = "Gruppenzeilen ebenfalls im Verlauf behalten. Aus behält nur Flüsternachrichten.",
	["Keep rares you already did quiet"] = "Bereits erledigte rare Gegner stumm lassen",
	["Keep showing the reminders from before the fight while in combat, frozen (the game does not let addons read auras in combat, so they update when combat ends). Off: reminders hide in combat."] = "Die Erinnerungen von vor dem Kampf im Kampf eingefroren weiter anzeigen (das Spiel lässt Addons im Kampf keine Auren lesen, daher aktualisieren sie sich nach dem Kampf). Aus: Erinnerungen werden im Kampf ausgeblendet.",
	["Keep the book and talent art"] = "Buch- und Talentgrafik behalten",
	["Keep the game's totem timers next to the player frame anyway."] = "Die Totemtimer des Spiels trotzdem neben dem Spielerrahmen behalten.",
	["Keep the plate texture"] = "Plakettentextur behalten",
