	["Learn first: %s"] = "Zuerst erlernen: %s",
	["Learn it on a %s: the planner offers it at login."] = "Erlernt ihn mit einem Charakter der Klasse %s: Der Planer bietet ihn beim Einloggen an.",
	["Learn next"] = "Nächsten erlernen",
	["Learn next and Learn to my level are the only buttons that spend points, and only when you click them. Plans are saved per character and talent group."] = "Nächsten erlernen und Bis zu meiner Stufe erlernen sind die einzigen Schaltflächen, die Punkte ausgeben, und nur, wenn Ihr sie anklickt. Pläne werden pro Charakter und Talentgruppe gespeichert.",
	["Learn spends one point on the next rank in your talent plan. EldoUI never spends a point unless you click, also not when you level up."] = "Erlernen gibt einen Punkt für den nächsten Rang in Eurem Talentplan aus. EldoUI gibt nie einen Punkt aus, ohne dass Ihr klickt, auch nicht beim Stufenaufstieg.",
	["Learn to my level"] = "Bis zu meiner Stufe erlernen",
	["Learn to my level (%d)"] = "Bis zu meiner Stufe erlernen (%d)",
	["Learned"] = "Erlernt",
	["Learned %d of them"] = "%d davon erlernt",
	["Learned by you"] = "Von Euch erlernt",
	["Learned flight time in tooltips"] = "Gelernte Flugzeit in Tooltips",
	["Learned: %s."] = "Erlernt: %s.",
	["Learning"] = "Erlernen",
	["Learns every rank your plan has up to your level, as far as your unspent points go, in one go."] = "Erlernt auf einmal jeden Rang Eures Plans bis zu Eurer Stufe, soweit Eure freien Punkte reichen.",
	["Learns how long each route takes from your own flights. While you fly, the route shows with its stops, the time left and the arrival time; Maps shows the times on the flight map."] = "Lernt aus Euren eigenen Flügen, wie lange jede Route dauert. Während Ihr fliegt, wird die Route mit ihren Zwischenstopps, der Restzeit und der Ankunftszeit angezeigt; Karten zeigt die Zeiten auf der Flugkarte.",
	["Learns the next rank of your plan. One click, one rank; nothing else is spent."] = "Erlernt den nächsten Rang Eures Plans. Ein Klick, ein Rang; sonst wird nichts ausgegeben.",
	["Learns this one rank now. Nothing else is spent."] = "Erlernt jetzt diesen einen Rang. Sonst wird nichts ausgegeben.",
	["Leave"] = "Verlassen",
	["Leave as it is"] = "Unverändert lassen",
	["Leave gray quests alone"] = "Graue Quests auslassen",
	["Leave group"] = "Gruppe verlassen",
	["Leave it when a queue pops"] = "Verlassen, wenn eine Warteschlange aufgeht",
	["Leave out ignored spells"] = "Ignorierte Zauber weglassen",
	["Leave out the herbalism, mining, skinning and fishing lines of professions you have not learned."] = "Die Zeilen zu Kräuterkunde, Bergbau, Kürschnerei und Angeln für Berufe weglassen, die Ihr nicht erlernt habt.",
	["Leave repeatable quests to me"] = "Wiederholbare Quests mir überlassen",
	["Leave the raid first."] = "Verlasst zuerst den Schlachtzug.",
	["Leave them"] = "Belassen",
	["Leave your group?"] = "Eure Gruppe verlassen?",
	["Leaves the group after you confirm. There is no disband button: removing everyone at once would be many actions from one click."] = "Verlässt die Gruppe, nachdem Ihr bestätigt habt. Eine Schaltfläche zum Auflösen gibt es nicht: Alle auf einmal zu entfernen wären viele Aktionen aus einem Klick.",
	["Ledger"] = "Kassenbuch",
	["Ledger dark"] = "Kassenbuch dunkel",
	["Ledgers"] = "Kassenbücher",
	["Left edge"] = "Linker Rand",
	["Left of the bars"] = "Links von den Leisten",
	["Left of the frame"] = "Links vom Rahmen",
	["Left of the map"] = "Links von der Karte",
	["Left out"] = "Weggelassen",
	["Left over"] = "Übrig",
	["Left over: %s"] = "Übrig: %s",
	["Left, rows down"] = "Links, Reihen nach unten",
	["Left, rows up"] = "Links, Reihen nach oben",
	["Left-click"] = "Linksklick",
	["Left-click a bar to open the quest log (XP), the reputation list, the PvP tab (honor) or your pet's page. Not in combat."] = "Linksklick auf eine Leiste öffnet das Questlog (EP), die Rufliste, den PvP-Reiter (Ehre) oder die Seite Eures Tiers. Nicht im Kampf.",
	["Left-click a talent: add a rank to the plan. Right-click: remove one. EldoUI learns only when you click Learn."] = "Linksklick auf ein Talent: dem Plan einen Rang hinzufügen. Rechtsklick: einen entfernen. EldoUI erlernt nur, wenn Ihr auf Erlernen klickt.",
	["Left-click makes your target a main assist, right-click removes it (Blizzard's /ma, out of combat)."] = "Linksklick macht Euer Ziel zum Hauptassistenten, Rechtsklick nimmt es zurück (Blizzards /ma, außerhalb des Kampfes).",
	["Left-click makes your target a main tank, right-click removes it (Blizzard's /mt, out of combat)."] = "Linksklick macht Euer Ziel zum Haupttank, Rechtsklick nimmt es zurück (Blizzards /mt, außerhalb des Kampfes).",
	["Left-click resets all your instances (group leader, or alone), the same as the portrait menu. Right-click announces the last reset when the Instances module allows it. Only ever on your click."] = "Linksklick setzt alle Eure Instanzen zurück (als Gruppenanführer oder allein), genau wie das Porträtmenü. Rechtsklick kündigt das letzte Zurücksetzen an, wenn das Modul Instanzen es erlaubt. Immer nur auf Euren Klick.",
	["Left-click starts the group countdown, right-click cancels it."] = "Linksklick startet den Gruppen-Countdown, Rechtsklick bricht ihn ab.",
	["Left-click to keep an item up. Right-click to change what is checked: its buff, Well Fed, or the main/off-hand weapon enchant."] = "Linksklick, um einen Gegenstand aktiv zu halten. Rechtsklick, um zu ändern, was geprüft wird: sein Stärkungszauber, Satt oder die Waffenverzauberung der Waffen-/Schildhand.",
	["Legacy reward track, challenges and Legacy tree window."] = "Vermächtnis-Belohnungspfad, Herausforderungen und Fenster des Vermächtnisbaums.",
	["Legacy window"] = "Vermächtnisfenster",
	["Length"] = "Länge",
	["Length of every bar in pixels. Full spans the whole screen."] = "Länge jeder Leiste in Pixeln. Voll reicht über den ganzen Bildschirm.",
	["Length of the pull countdown."] = "Länge des Pull-Countdowns.",
	["Let Blizzard draw private (boss mechanic) auras on this frame. Needs the Private auras switch on the Blizzard UI page."] = "Blizzard private Auren (Bossmechaniken) auf diesem Rahmen zeichnen lassen. Braucht den Schalter Private Auren auf der Seite Blizzard-UI.",
	["Let EldoUI place the bag bar"] = "EldoUI die Taschenleiste platzieren lassen",
	["Let EldoUI place the micro menu"] = "EldoUI das Mikromenü platzieren lassen",
	["Let EldoUI place the minimap buttons"] = "EldoUI die Minikartenschaltflächen platzieren lassen",
	["Lets the Post buttons send one line to your raid or party: the reservations for an item, or the ledger totals. Each click sends one line."] = "Lässt die Posten-Schaltflächen eine Zeile an Euren Schlachtzug oder Eure Gruppe senden: die Reservierungen für einen Gegenstand oder die Summen des Kassenbuchs. Jeder Klick sendet eine Zeile.",
