	["Pop-ups"] = "Pop-ups",
	["Pop-ups appear where the 'Pop-up dialogs' mover sits (/eui move)."] = "Pop-ups erscheinen dort, wo das Verschiebefeld „Dialogfenster“ sitzt (/eui move).",
	["Pop-ups follow their mover"] = "Pop-ups folgen ihrem Verschiebefeld",
