	["Precise"] = "Präzise",
	["Precise coordinates for you and the cursor in larger text. The map's size is on the Move windows page."] = "Präzise Koordinaten für Euch und den Cursor in größerer Schrift. Die Kartengröße steht auf der Seite Fenster verschieben.",
	["Precision"] = "Genauigkeit",
	["Prerequisite arrows"] = "Voraussetzungspfeile",
	["Press Ctrl+C to copy. Newest first."] = "Drückt Strg+C zum Kopieren. Neueste zuerst.",
	["Press Ctrl+C to copy. Paste the lines into Paste waypoints to add them again."] = "Drückt Strg+C zum Kopieren. Fügt die Zeilen in „Wegpunkte einfügen“ ein, um sie wieder hinzuzufügen.",
	["Press Ctrl+C, open chat, paste the command and press Enter."] = "Drückt Strg+C, öffnet den Chat, fügt den Befehl ein und drückt die Eingabetaste.",
	["Press a key (Escape clears)"] = "Drückt eine Taste (Esc löscht)",
	["Preview the toast"] = "Vorschau des Hinweises",
	["Price source"] = "Preisquelle",
	["Prices"] = "Preise",
	["Prices as"] = "Preise als",
	["Print the gold collected"] = "Eingesammeltes Gold im Chat anzeigen",
	["Print what was earned and spent"] = "Einnahmen und Ausgaben im Chat anzeigen",
	["Priority: style filter, tapped, another tank, threat, health, class, friendly, boss, rare elite, miniboss, rare, quest, elite, reaction."] = "Priorität: Stilfilter, beansprucht, anderer Tank, Bedrohung, Gesundheit, Klasse, freundlich, Boss, rare Elite, Miniboss, rar, Quest, Elite, Reaktion.",
	["Private Boss Warnings"] = "Private Bosswarnungen",
	["Private auras"] = "Private Auren",
	["Private boss emotes show at the Private Boss Warnings mover (needs Move on for Private auras)."] = "Private Boss-Emotes erscheinen am Verschiebefeld „Private Bosswarnungen“ (benötigt Verschieben für Private Auren).",
	["Problems (unmatched brackets, too long) stop a macro from working. Warnings name a command, condition, spell or item the game does not know right now; a spell you learn later is fine."] = "Probleme (nicht geschlossene Klammern, zu lang) verhindern, dass ein Makro funktioniert. Warnungen nennen einen Befehl, eine Bedingung, einen Zauber oder Gegenstand, den das Spiel gerade nicht kennt; ein Zauber, den Ihr später erlernt, ist in Ordnung.",
	["Problems and warnings"] = "Probleme und Warnungen",
	["Problems only"] = "Nur Probleme",
	["Profession Planner"] = "Berufsplaner",
	["Profession trainer"] = "Berufslehrer",
	["Profession trainers"] = "Berufslehrer",
	["Progress and timer bars with the EldoUI bar texture and a 1 px border."] = "Fortschritts- und Timerleisten mit der EldoUI-Leistentextur und einem 1-px-Rand.",
	["Progress bars"] = "Fortschrittsleisten",
	["Progress popups"] = "Fortschritts-Pop-ups",
	["Prompt sound"] = "Anfrageton",
	["Prompts and reward values on; no blocks, no quest helpers; game, sound and graphics settings left alone."] = "Anfragen und Belohnungswerte an; keine Blockierungen, keine Questhelfer; Spiel-, Ton- und Grafikeinstellungen bleiben unberührt.",
	["Protect quest and recipe items"] = "Quest- und Rezeptgegenstände schützen",
	["Protected settings"] = "Geschützte Einstellungen",
	["Protected settings are not listed. The window closes in combat, and nothing changes in combat."] = "Geschützte Einstellungen werden nicht aufgeführt. Das Fenster schließt sich im Kampf, und im Kampf ändert sich nichts.",
	["Pull"] = "Pull",
	["Pull countdown"] = "Pull-Countdown",
	["Pulse glow"] = "Pulsierendes Leuchten",
	["Purge, steal, enrage"] = "Bannen, Stehlen, Raserei",
	["Put Questie's tracker on the mover"] = "Questies Verfolgung auf das Verschiebefeld setzen",
	["Put a button on the side rail first."] = "Legt zuerst eine Schaltfläche auf die Seitenleiste.",
	["Put down what is on your cursor first, then restore the snapshot."] = "Legt zuerst ab, was Ihr am Cursor habt, und stellt dann den Schnappschuss wieder her.",
	["Put new spells on the bars"] = "Neue Zauber auf die Leisten legen",
	["Put the backpack at the end of the row instead of the start."] = "Den Rucksack ans Ende der Reihe statt an den Anfang setzen.",
	["Put the cast bar on its own mover (Player Cast Bar) instead of under the frame."] = "Die Zauberleiste auf ein eigenes Verschiebefeld (Spieler-Zauberleiste) statt unter den Rahmen setzen.",
	["Put this plate above overlapping plates."] = "Diese Plakette über überlappende Plaketten legen.",
	["Put this tab's settings back to EldoUI's defaults. This type's on/off switch stays as it is."] = "Die Einstellungen dieses Reiters auf die Standardwerte von EldoUI zurücksetzen. Der An/Aus-Schalter dieses Typs bleibt, wie er ist.",
	["Puts a map pin on your nearest class trainer."] = "Setzt eine Kartenmarkierung auf Euren nächsten Klassenlehrer.",
	["Puts a map pin on your nearest portal trainer."] = "Setzt eine Kartenmarkierung auf Euren nächsten Portallehrer.",
	["Puts a map pin where the class quest starts."] = "Setzt eine Kartenmarkierung dort, wo die Klassenquest beginnt.",
	["Puts back the macro text from before its last spell rank update (out of combat, until you log out)."] = "Stellt den Makrotext von vor dem letzten Zauberrang-Update wieder her (außerhalb des Kampfes, bis Ihr Euch ausloggt).",
	["Puts back your own value from before EldoUI changed this setting."] = "Stellt Euren eigenen Wert von vor der Änderung durch EldoUI wieder her.",
	["Puts back your own value of every setting changed in this browser. Settings other EldoUI pages set stay."] = "Stellt Euren eigenen Wert jeder in diesem Browser geänderten Einstellung wieder her. Einstellungen, die andere EldoUI-Seiten gesetzt haben, bleiben.",
	["Puts back your own value of every setting you changed in the browser. Rows on this page and other EldoUI pages keep theirs."] = "Stellt Euren eigenen Wert jeder Einstellung wieder her, die Ihr im Browser geändert habt. Zeilen auf dieser Seite und anderen EldoUI-Seiten behalten ihre.",
	["Puts every addon button you kept on the map back in the bin."] = "Legt jede Addon-Schaltfläche, die Ihr auf der Karte behalten habt, zurück in die Ablage.",
	["Puts every game setting EldoUI changed (these rows, camera and screenshots) back to your own values and sets the rows to \"Game setting\"."] = "Setzt jede Spieleinstellung, die EldoUI geändert hat (diese Zeilen, Kamera und Screenshots), auf Eure eigenen Werte zurück und stellt die Zeilen auf „Spieleinstellung“.",
	["Puts every missing reagent on the auction house shopping list \"Profession Planner\". You still search and buy yourself."] = "Setzt jedes fehlende Reagenz auf die Auktionshaus-Einkaufsliste „Profession Planner“ (Berufsplaner). Suchen und kaufen müsst Ihr weiterhin selbst.",
	["Puts the preview's weapons away, or draws them again."] = "Steckt die Waffen der Vorschau weg oder zieht sie wieder.",
	["Puts this player on your ignore list after you confirm. Their whispers and chat stop reaching you."] = "Setzt diesen Spieler nach Eurer Bestätigung auf Eure Ignorierliste. Sein Flüstern und seine Chatnachrichten erreichen Euch nicht mehr.",
	["Puts this starter scale back to EldoUI's values (for a spec scale: back to EldoUI's stat priority)."] = "Setzt diese Startskala auf die Werte von EldoUI zurück (bei einer Spezialisierungsskala: auf EldoUIs Werte-Priorität).",
	["PvP"] = "PvP",
