	["Quest window"] = "Questfenster",
	["Quest, gossip and other NPC dialogs, the pet stable and the barber shop in the EldoUI look."] = "Quest-, Gesprächs- und andere NSC-Dialoge, der Tierstall und der Barbier in der EldoUI-Optik.",
	["Quest: %s"] = "Quest: %s",
	["Questie"] = "Questie",
	["Questie's tracker gets the EldoUI panel instead of its own background. Needs the tracker's Skin switch."] = "Questies Verfolgung erhält das EldoUI-Panel statt ihres eigenen Hintergrunds. Benötigt den Skin-Schalter der Verfolgung.",
	["Questie's tracker sits on the Quest tracker mover; drag that mover instead of Questie's frame. Needs the tracker's Move and scale switch. Turn on Hide for Blizzard's tracker if both show."] = "Questies Verfolgung sitzt auf dem Verschiebefeld Questverfolgung; zieht dieses Verschiebefeld statt Questies Rahmen. Benötigt den Schalter „Verschieben und skalieren“ der Verfolgung. Schaltet „Ausblenden“ für Blizzards Verfolgung ein, wenn beide erscheinen.",
	["Questing"] = "Questen",
	["Quests and gossip"] = "Quests und Gespräche",
	["Quests done together: %d (%s)."] = "Gemeinsam erledigte Quests: %d (%s).",
	["Quests in this color are new in WoW: Forever; the original game did not have them. The Quest Marks page changes the color or turns the marks off."] = "Quests in dieser Farbe sind neu in WoW: Forever; das ursprüngliche Spiel hatte sie nicht. Die Seite Questmarkierungen ändert die Farbe oder schaltet die Markierungen aus.",
	["Quests new in WoW: Forever get a tag in the quest window and a tint in the quest log, tracker, tooltips and world map. Also: /eui newquest."] = "Neue Quests in WoW: Forever erhalten eine Kennzeichnung im Questfenster und eine Tönung im Questlog, in der Verfolgung, in Tooltips und auf der Weltkarte. Auch: /eui newquest.",
	["Quests shared by people who aren't friends are declined. Off by default."] = "Quests, die von Leuten geteilt werden, die keine Freunde sind, werden abgelehnt. Standardmäßig aus.",
	["Quick Join skin"] = "Skin für Schnellbeitritt",
