	["Show +Combat / -Combat"] = "+Kampf / -Kampf anzeigen",
	["Show EldoUI's frame for this unit. Units Blizzard draws too (player, target, focus, pet, boss) show only while Blizzard UI lets EldoUI replace or hide Blizzard's frame, so the unit never shows twice."] = "Den EldoUI-Rahmen für diese Einheit anzeigen. Einheiten, die auch Blizzard zeichnet (Spieler, Ziel, Fokus, Begleiter, Boss), erscheinen nur, solange Blizzard-UI EldoUI erlaubt, Blizzards Rahmen zu ersetzen oder auszublenden, damit die Einheit nie doppelt erscheint.",
	["Show HandyNotes"] = "HandyNotes anzeigen",
	["Show HandyNotes' pins (with all its plugins). Off turns HandyNotes off until you check it again."] = "Die Markierungen von HandyNotes anzeigen (mit allen Plugins). Aus schaltet HandyNotes ab, bis Ihr es wieder anhakt.",
	["Show a card"] = "Eine Karte anzeigen",
	["Show a consumable reminder (grayed) even when you carry none of it. Off: only when you have one to use."] = "Eine Verbrauchsgut-Erinnerung (ausgegraut) auch zeigen, wenn Ihr nichts davon dabeihabt. Aus: nur, wenn Ihr eines benutzen könnt.",
	["Show a new quest's title in the tint color in the quest window. Off: only the tag marks it."] = "Den Titel einer neuen Quest im Questfenster in der Tönungsfarbe zeigen. Aus: nur die Kennzeichnung markiert sie.",
	["Show a sample card and play the sound with your settings."] = "Eine Beispielkarte zeigen und den Ton mit Euren Einstellungen abspielen.",
	["Show a small tag in the corner of the quest window for new quests."] = "Eine kleine Kennzeichnung in der Ecke des Questfensters für neue Quests zeigen.",
	["Show a test pop-up"] = "Test-Pop-up anzeigen",
